entries[351086] = { ["name"] = "Überwältigende Macht", ["text"] = "300 Meter Reichweite\nSofort\nSo'leah bindet sich an die Relikte und nutzt ihre Macht, um für jedes verbundene Relikt ihren sämtlichen erlittenen Schaden um 99% zu verringern.\n\nWenn ein Relikt mit ' Hyperlichtschock ' getroffen wird, wird die Verbindung mit So'leah unterbrochen." }
