entries[351091] = { ["name"] = "Destabilisieren", ["text"] = "40 Meter Reichweite\nWirken in 2 sek. 6 sek. Abklingzeit\nDer Hoffnungsbrecher kanalisiert destabilisierende Magie auf betroffene Ziele, verringert ihre Bewegungsgeschwindigkeit um 5%, fügt ihnen pro Sekunde 399 Schattenschaden zu und absorbiert zusätzlich Heilung in Höhe von 10% der Gesundheit des Ziels. Hält 6 Sek. lang an. Dieser Effekt ist stapelbar." }
entries[351092] = { ["name"] = "Destabilisieren", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Hoffnungsbrecher kanalisiert destabilisierende Magie auf betroffene Ziele, verringert ihre Bewegungsgeschwindigkeit um 5%, fügt ihnen pro Sekunde 399 Schattenschaden zu und absorbiert zusätzlich Heilung in Höhe von 10% der Gesundheit des Ziels. Hält 6 Sek. lang an. Dieser Effekt ist stapelbar." }
entries[351093] = { ["name"] = "Widerstandsfähige Näherei", ["text"] = "Seelenbandefähigkeit\nWenn Eure Gesundheit über 90% liegt, erhaltet Ihr für 1 Min. einen Schild, der (Gesamtgesundheit * 16 / 100) Magieschaden absorbiert. Dieser Effekt kann nur einmal alle 1 Min. auftreten." }
entries[351094] = { ["name"] = "Pusteleruption", ["text"] = "Seelenbandefähigkeit\n'Fleischformung' bedeckt Euch pro kanalisierter Sekunde mit 3 Pusteln. Wenn Ihr Schaden erleidet oder geheilt werdet, platzt eine Pustel, fügt Gegnern in der Nähe [Angriffskraft * 0.72 * (1 + Vielseitigkeit)] Naturschaden zu und heilt Verbündete in der Nähe um (Angriffskraft * 0.48) Gesundheit. Diese Werte werden auf die Gegner und Verbündeten aufgeteilt.\n(700ms Abklingzeit)" }
