entries[352186] = { ["name"] = "Spektrometer des Seelenglanzes", ["text"] = "Seelenbandefähigkeit\nWenn Ihr ein Ziel heilt oder ihm Schaden zufügt, wird im Verlauf von 15 Sek. sein Wert analysiert. Dies erhöht Euren Schaden oder Eure Heilung bei diesem Ziel um 1% und alle 3 Sek. um weitere 1%.\n\nIhr könnt keine neue Analyse beginnen, bevor die vorherige dieser Art abgeschlossen ist." }
entries[352187] = { ["name"] = "Reaktives Umrüsten", ["text"] = "Seelenbandefähigkeit\nNachdem Ihr körperlichen oder Magieschaden erleidet, erhaltet Ihr einen Schild, der 10 Sek. lang Schaden in Höhe von 6% Eurer maximalen Gesundheit absorbiert.\n\nJede eintreffende Schadensart kann diesen Effekt einmal alle 30 Sek. auslösen." }
entries[352188] = { ["name"] = "Auslaufender Animabeschleuniger", ["text"] = "Seelenbandefähigkeit\nWenn Ihr Eure Kyrianerklassenfähigkeit aktiviert, wird eine Explosion überladener Anima an der Position Eures Ziels entfesselt, die über 8 Sek. [ 1 * (45 / 100 * Max(Angriffskraft, Zaubermacht) * (1 + Vielseitigkeit)) * 5] gleichmäßig aufgeteilten Arkanschaden verursacht.\n\nVerringert die Abklingzeit Eurer Kyrianerklassenfähigkeit pro getroffenem Gegner um ( 4 ) Sek., bis zu maximal ( 4 * 5) Sek." }
