entries[352387] = { ["name"] = "Überrest: Mort'regars Echos", ["text"] = "Sofort\nDie Macht der Oberen Ebenen erhöht den verursachten körperlichen Schaden der Streitkräfte des Kerkermeisters um 50%. Ein Spielercharakter kann diesen Effekt verringern, indem er einen Teil der Qual absorbiert. Dadurch erleidet der Spielercharakter 10 Min. lang 10% mehr körperlichen Schaden." }
