entries[352389] = { ["name"] = "Überrest: Mort'regars Echos", ["text"] = "Sofort\nMort'regars Echos erhöhen den verursachten Magieschaden der Streitkräfte des Kerkermeisters um 50%. Ein Spielercharakter kann diesen Effekt verringern, indem er einen Teil der Qual absorbiert. Dadurch erleidet der Spielercharakter 10 Min. lang 10% mehr Magieschaden." }
entries[352390] = { ["name"] = "Rissschläge", ["text"] = "300 Meter Reichweite\nWirken in 3 sek. 5 sek. Abklingzeit\nDer Zaubernde entfesselt Rissschläge aus den Mittlerportalen in der Nähe, die Arkanschaden verursachen." }
