entries[352392] = { ["name"] = "Überrest: Seelenschmiedehitze", ["text"] = "Sofort\nSeelenschmiedehitze fügt allen Spielercharakteren regelmäßig 31963 Feuerschaden zu. Ein Spielercharakter kann diesen Effekt verringern, indem er einen Teil der Qual absorbiert. Dadurch erleidet der Spielercharakter 10 Min. lang alle 5 Sek. 8 Feuerschaden." }
entries[352393] = { ["name"] = "Rissschläge", ["text"] = "200 Meter Reichweite\nWirken in 6 sek.\nPortalmagier öffnen Risse, die kurze Zeit später Energie ausstoßen und allen Spielercharakteren in einer Linie 12 Arkanschaden zufügen." }
entries[352394] = { ["name"] = "Strahlende Energie", ["text"] = "300 Meter Reichweite\nSofort\nWährend er aktiv ist, gibt der Energiekern ein Feld von ' Strahlende Energie ' ab. Spielercharaktere im Effektbereich erleiden 80% weniger Schaden durch ' Instabile Energie '." }
